#include <iostream>
#include <vector>
#include <algorithm>
int main() {
    std::vector<int> v = {5, 2, 9, 1, 5, 6};
    std::sort(v.begin(), v.end());
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';
    std::sort(v.begin(), v.end(), std::greater<int>());
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';
}
